// Convert Polygon2d to CGAL polygons
internal::Polygon_2 cgal_p1, cgal_p2;
for (const auto& p : P1) {
    cgal_p1.push_back(internal::Point_2(p.x(), p.y()));
}
for (const auto& p : P2) {
    cgal_p2.push_back(internal::Point_2(p.x(), p.y()));
}

// Perform difference operation using CGAL
internal::Pwh_list_2 diff_result;
CGAL::difference(cgal_p1, cgal_p2, diff_result);

// Convert the result back to our polygon format
std::vector<PolygonWithHoles2d> result;
for (const auto& poly_with_holes : diff_result) {
    PolygonWithHoles2d pwh;
    // Add outer boundary
    std::vector<Point2d> outer_boundary;
    for (const auto& vertex : poly_with_holes.outer_boundary()) {
        double x, y;
        internal::getCoordinates(vertex, x, y);
        outer_boundary.emplace_back(x, y);
    }
    pwh.setOuterBoundary(outer_boundary);

    // Add holes
    for (const auto& hole : poly_with_holes.holes()) {
        std::vector<Point2d> hole_points;
        for (const auto& vertex : hole) {
            double x, y;
            internal::getCoordinates(vertex, x, y);
            hole_points.emplace_back(x, y);
        }
        pwh.addHole(hole_points);
    }
    result.push_back(pwh);
}

return result;

